package io.rift.cronos;

import android.app.*;
import android.os.Bundle;
import android.content.Intent;
import android.graphics.Color;
import android.net.Uri;
import android.text.InputType;
import android.widget.*;
import org.json.*;
import java.io.*;
import java.util.concurrent.*;

/** Native-only settings/workspace. Deliberately no WebView, JS bridge, seed entry or signer. */
public final class HybridActivity extends Activity {
    private LinearLayout body;private TextView output;
    private EditText rpc,key,backupRpc,backupKey,cloud,gateway,profile,owner,contract,token,hash,title,document;
    private CheckBox clearKey,clearBackup,multi;
    private SecureConnections connections;private LocalWorkspace workspace;private ReceiptWatchStore watches;private final ExecutorService io=Executors.newSingleThreadExecutor();
    private byte[] pendingExport;private static final int EXPORT=81,IMPORT=82;private volatile boolean working;
    private interface Job {String run() throws Exception;}
    @Override public void onCreate(Bundle state){super.onCreate(state);getWindow().setFlags(android.view.WindowManager.LayoutParams.FLAG_SECURE,android.view.WindowManager.LayoutParams.FLAG_SECURE);connections=new SecureConnections(this);workspace=new LocalWorkspace(this);watches=new ReceiptWatchStore(this);setResult(RESULT_OK);render();}
    private int dp(int value){return (int)(value*getResources().getDisplayMetrics().density);}
    private void text(String message){TextView view=new TextView(this);view.setText(message);view.setTextColor(Color.rgb(220,225,238));view.setTextSize(15);view.setPadding(0,dp(12),0,dp(8));body.addView(view);}
    private EditText field(String label,String hint,boolean secret){text(label);EditText view=new EditText(this);view.setContentDescription(label);view.setTextColor(Color.WHITE);view.setHintTextColor(Color.LTGRAY);view.setHint(hint);view.setSingleLine(true);view.setInputType(InputType.TYPE_CLASS_TEXT|(secret?InputType.TYPE_TEXT_VARIATION_PASSWORD:InputType.TYPE_TEXT_FLAG_NO_SUGGESTIONS));view.setImportantForAutofill(android.view.View.IMPORTANT_FOR_AUTOFILL_NO_EXCLUDE_DESCENDANTS);body.addView(view);return view;}
    private void button(String label,Runnable action){Button button=new Button(this);button.setText(label);button.setOnClickListener(v->action.run());body.addView(button);}
    private CheckBox check(String label){CheckBox view=new CheckBox(this);view.setText(label);view.setTextColor(Color.WHITE);body.addView(view);return view;}
    private Spinner choices(String label,String[] labels){text(label);Spinner picker=new Spinner(this);picker.setContentDescription(label);picker.setBackgroundColor(Color.LTGRAY);picker.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,labels));body.addView(picker);return picker;}
    private void rpcOptions(String slot,EditText endpoint,EditText credential,CheckBox remove){
        Spinner picker=choices(slot+" provider options",ConnectionPresets.RPC_LABELS);
        Spinner auth=choices(slot+" authentication help",new String[]{"No API key · public RPC", "API key in provider URL · paste full URL", "Authorization Bearer · provider token", "Other header scheme · not supported"});
        button("Explain "+slot+" authentication option",()->{String[] help={"Public RPC: no account token needed. Apply a public preset, Save, then Test. Rate limits and provider privacy policies still apply.","Paste the full provider-issued HTTPS RPC URL in this slot. Do not paste only the key, and do not duplicate a URL key in the Bearer field. URL paths stay protected in native settings.","Paste the provider's token in this slot's Bearer field only if its docs require Authorization: Bearer. Blank keeps the old token unless the endpoint changes; remove explicitly when no longer needed.","Custom x-api-key/basic headers are not implemented. Use a compatible provider-issued URL or documented Bearer endpoint instead. Never enter a wallet seed/private key."};show(help[auth.getSelectedItemPosition()]);});
        button("Apply "+slot+" provider to editable fields (not saved)",()->{
            int index=picker.getSelectedItemPosition();String preset=ConnectionPresets.rpc(index);
            if(preset.isEmpty()){show("Manual input selected. Edit the HTTPS URL below; blank RPC keeps the saved value. Nothing saved or contacted.");endpoint.requestFocus();return;}
            endpoint.setText(preset);credential.setText("");remove.setChecked(false);
            show(slot+" public preset filled; no network request or save. Its credential field was cleared. Save explicitly, then Test saved "+slot.toLowerCase(java.util.Locale.ROOT)+" connection. Changing host clears the saved token. Public services may rate-limit and see your IP/read requests.");
        });
    }
    private void show(String value){output.setText(value);}
    private void job(Job task){if(isFinishing()||isDestroyed())return;if(working){show("A local operation is already running. Wait for it to finish.");return;}working=true;show("Working… No transaction will be signed or sent.");io.execute(()->{String result;try{result=task.run();}catch(ReadOnlyRpc.ProviderFailure e){result=e.getMessage();}catch(IllegalArgumentException|IllegalStateException e){result=e.getMessage();}catch(Exception e){result="Operation failed. Check connection/settings or import format. Credentials and provider response details are intentionally not logged.";}final String message=result;runOnUiThread(()->{working=false;if(!isFinishing()&&!isDestroyed())show(message);});});}
    private String account() {return LocalWorkspace.account(profile.getText().toString());}
    private JSONObject readConnections() throws Exception {JSONObject value=connections.load();if(value.optString("mode").equals("offline"))throw new IllegalStateException("Network access is paused. Connect saved services first.");return value;}
    private ReadOnlyRpc primary(JSONObject value){return new ReadOnlyRpc(value.optString("rpc"),value.optString("key"));}
    private void render(){
        body=new LinearLayout(this);body.setOrientation(LinearLayout.VERTICAL);body.setPadding(dp(20),dp(24),dp(20),dp(32));body.setBackgroundColor(Color.rgb(9,11,18));ScrollView scroll=new ScrollView(this);scroll.addView(body);setContentView(scroll);scroll.setOnApplyWindowInsetsListener((v,insets)->{v.setPadding(insets.getSystemWindowInsetLeft(),insets.getSystemWindowInsetTop(),insets.getSystemWindowInsetRight(),insets.getSystemWindowInsetBottom());return insets;});scroll.requestApplyInsets();
        text("RIFT · ADVANCED SETTINGS\nBackend-connected testing build · Cronos 25\nNo seed phrase, private key, signing or automatic spending.");
        JSONObject saved;try{saved=connections.load();}catch(Exception e){text("Protected settings could not be unlocked. Do not silently reset them. Use Forget connections below to explicitly reset.");saved=new JSONObject();}
        text("RENDER BACKEND · ONE CONNECTED APP\nThe app connects to the backend by default. You can pause/reconnect networking below. RPC/IPFS controls are advanced diagnostics, not alternate app modes. Wallet keys and seed phrases stay on this device.");
        button("Native wallet vault · experimental, no transaction signing",()->startActivity(new Intent(this,WalletActivity.class)));
        rpc=field("Primary RPC URL (HTTPS)","Blank keeps saved URL",true);key=field("Replace primary Bearer token (optional)","Blank keeps current token",true);clearKey=check("Remove saved primary token");
        backupRpc=field("Backup RPC URL (optional)","Blank keeps saved URL",true);backupKey=field("Replace backup Bearer token (optional)","Blank keeps current token",true);clearBackup=check("Remove backup URL and token");
        rpcOptions("Primary",rpc,key,clearKey);rpcOptions("Backup",backupRpc,backupKey,clearBackup);
        text("Custom provider authentication: paste the complete provider-issued HTTPS URL if the key is in its path/query, OR enter a Bearer token only if the provider documents Bearer authentication. Never enter wallet seeds/private keys. Provider-specific x-api-key headers are not supported; do not put such keys in the Bearer field. Manual endpoints remain editable after choosing any preset.");
        gateway=field("IPFS gateway HTTPS origin (native JSON/artwork reads)","https://ipfs.io",false);gateway.setText(saved.optString("gateway","https://ipfs.io"));
        Spinner gatewayPicker=choices("IPFS gateway options",new String[]{"Manual / keep entered origin","ipfs.io public gateway","dweb.link public gateway"});
        button("Apply IPFS gateway to editable field (not saved)",()->{int i=gatewayPicker.getSelectedItemPosition();if(i>0)gateway.setText(i==1?"https://ipfs.io":"https://dweb.link");else gateway.requestFocus();show("Gateway field only; Save explicitly. Enter a lowercase public HTTPS origin, no port/path/query/key. Only bounded /ipfs/CID paths are requested, with separate consent. Redirects are refused; some public gateways redirect and will not work. No fallback, pinning or retention guarantee.");});
        cloud=field("Backend API origin (advanced)",BackendConnectionPolicy.DEFAULT_ORIGIN,false);cloud.setText(saved.optString("cloud",BuildConfig.RIFT_ORIGIN));
        Spinner servicePicker=choices("Shared API hosting options (your deployment required)",ConnectionPresets.SERVICE_LABELS);
        button("Show selected shared API setup option",()->show(ConnectionPresets.serviceHelp(servicePicker.getSelectedItemPosition())));
        text("OTHER API SECTIONS · capability guide\nIPFS JSON/artwork read: choose a native gateway preset or manually enter a public HTTPS origin above. Use manual ipfs:// CID/path input in the bundled read panel. Gateway switching requires Save and a new consent; no authentication/redirects/fallback.\nDiscovery/rankings/metadata API: supplied by your compatible shared RIFT backend, not interchangeable provider URLs. Choose a shared hosting option above and enter its real origin.\nUploads/sponsored pinning: backend authorization only; never paste a permanent pinning secret into drafts or browser storage. Configure provider secrets on your own backend. No direct provider picker is enabled without a compatible adapter.\nWalletConnect project ID, marketplace/deployer contract addresses and backend upstream API keys: deployment/build configuration, not native connection credentials. No seed/private-key input is offered.\nExplorer links: existing Cronos explorer links, not a read API credential. These unavailable controls are described honestly rather than saving settings the app cannot use.");
        text("Saved primary host: "+NetworkPolicy.displayHost(saved.optString("rpc"))+"\nSaved backup host: "+NetworkPolicy.displayHost(saved.optString("backupRpc"))+"\nTokens and full RPC paths are never shown. URL-based credentials are supported; Bearer fields are only for providers using Authorization: Bearer. Keys do not auto-renew. Changing an endpoint clears its old token unless you explicitly enter a replacement. Shared-service changes also change the WebView origin; export browser drafts before switching.");
        button("Save edited settings & disconnect until validated",()->{
            final String r=rpc.getText().toString().trim(),k=key.getText().toString(),b=backupRpc.getText().toString().trim(),bk=backupKey.getText().toString(),c=cloud.getText().toString().trim(),gw=gateway.getText().toString().trim();final boolean ck=clearKey.isChecked(),cb=clearBackup.isChecked();
            job(()->{JSONObject value=connections.load();value.put("mode","offline").put("connectionChoice","paused");if(!r.isEmpty()){if(!r.equals(value.optString("rpc")))value.put("key","");value.put("rpc",r);}if(ck||(!r.isEmpty()&&ConnectionPresets.publicRpc(r)&&k.isEmpty()))value.put("key","");else if(!k.isEmpty())value.put("key",k);if(cb){value.put("backupRpc","");value.put("backupKey","");}else{if(!b.isEmpty()){if(!b.equals(value.optString("backupRpc")))value.put("backupKey","");value.put("backupRpc",b);}if(!b.isEmpty()&&ConnectionPresets.publicRpc(b)&&bk.isEmpty())value.put("backupKey","");else if(!bk.isEmpty())value.put("backupKey",bk);}value.put("cloud",c);value.put("gateway",MetadataPolicy.gateway(gw));if(c.isEmpty())throw new IllegalArgumentException("Backend HTTPS origin is required; use Reset for Render defaults");connections.save(value);ReceiptWatchScheduler.pause(this);runOnUiThread(()->{rpc.setText("");key.setText("");backupRpc.setText("");backupKey.setText("");clearKey.setChecked(false);clearBackup.setChecked(false);});return "Settings saved protected and DISCONNECTED. Tap Connect saved services to validate and enable them. Return to the app to apply the saved backend settings. Background receipt checks are paused after settings changes; resume explicitly if wanted. Endpoint validity is not provider trust or availability.";});
        });
        button("Connect saved services (validate backend before enabling)",()->job(()->{JSONObject value=connections.load();String revision=value.getString("_readRevision");if(value.optString("cloud").isEmpty())throw new IllegalStateException("No backend configured; use Reset for Render defaults");{PinnedHttps.Result health;try(RequestControl control=new RequestControl(15000)){health=PinnedHttps.health(value.getString("cloud"),control);}if(health.status!=200)throw new IllegalStateException("Shared API health check failed; not connected");JSONObject h=new JSONObject(JsonBudget.check(new String(health.body,java.nio.charset.StandardCharsets.UTF_8),65536,12));if(!h.optString("status").equals("ok")||h.optInt("chainId",-1)!=25)throw new IllegalStateException("Shared API health response not ready");}if(!revision.equals(connections.load().getString("_readRevision")))throw new IllegalStateException("Settings changed; retry validation");value.put("mode","hybrid").put("connectionChoice","connected");connections.save(value);ReceiptWatchScheduler.pause(this);return "Backend connected. HTTPS health and Cronos chain 25 checked. Native RPC diagnostics are optional and separate. Gateway content fetch still requires separate consent; status is not uptime/completeness certification. Close settings to apply. Typed fields must be Saved first.";}));
        button("Remove shared API origin & disconnect (keep wallet)",()->job(()->{JSONObject value=connections.load();value.put("cloud","").put("mode","offline").put("connectionChoice","paused");connections.save(value);ReceiptWatchScheduler.pause(this);return "Shared API origin removed; all networking disconnected. Existing browser-origin drafts/session cookies are not deleted or migrated; this does not revoke credentials at a remote provider. Local wallet untouched. Close settings to apply.";}));
        button("Disconnect all network services (keep saved settings)",()->job(()->{connections.disconnect();ReceiptWatchScheduler.pause(this);return "Disconnected. Saved endpoints retained. Close settings to cancel/reload the app channels; network remains paused across restarts until you explicitly Connect. No wallet or drafts deleted.";}));
        button("Reset to Render backend defaults",()->new AlertDialog.Builder(this).setTitle("Reset connection settings?").setMessage("Removes saved provider credentials and restores the Render backend and default Cronos RPC. Wallet and drafts are NOT deleted. The app will connect to Render on launch.").setPositiveButton("Reset & connect",(d,w)->job(()->{connections.save(SecureConnections.defaults());ReceiptWatchScheduler.pause(this);return "Render backend defaults restored. Close settings to reconnect. Wallet/drafts unchanged; trading still depends on server configuration.";})).setNegativeButton("Cancel",null).show());
        button("Test saved primary connection",()->job(()->{JSONObject value=readConnections();ReadOnlyRpc client=primary(value);client.requireCronos();return "Primary host: "+NetworkPolicy.displayHost(value.getString("rpc"))+"\nCronos chain ID: 25\nBlock: "+client.call("eth_blockNumber",new JSONArray())+"\nRead-only test passed. Not a contract or uptime audit.";}));
        button("Test saved backup connection",()->job(()->{JSONObject value=readConnections();if(value.optString("backupRpc").isEmpty())throw new IllegalArgumentException("No backup saved");ReadOnlyRpc client=new ReadOnlyRpc(value.getString("backupRpc"),value.optString("backupKey"));client.requireCronos();return "Backup host: "+NetworkPolicy.displayHost(value.getString("backupRpc"))+"\nCronos chain ID 25 verified. Backup use is explicit, never credential forwarding.";}));
        button("Use backup as primary (explicit swap)",()->job(()->{JSONObject value=readConnections();if(value.optString("backupRpc").isEmpty())throw new IllegalArgumentException("No backup saved");String old=value.optString("rpc"),oldKey=value.optString("key");value.put("rpc",value.getString("backupRpc")).put("key",value.optString("backupKey")).put("backupRpc",old).put("backupKey",oldKey);connections.save(value);ReceiptWatchScheduler.pause(this);return "Primary/backup slots swapped with their own credentials. Background receipt checks paused; resume explicitly after testing.";}));
        button("Forget saved credentials & pause networking",()->new AlertDialog.Builder(this).setTitle("Delete saved connections?").setMessage("Deletes this app's stored connection settings, not credentials at the provider. Local drafts and on-chain orders are unchanged.").setPositiveButton("Forget",(d,w)->job(()->{connections.clear();ReceiptWatchScheduler.pause(this);return "Provider credentials reset; networking paused until you explicitly reconnect. Wallet/drafts unchanged.";})).setNegativeButton("Cancel",null).show());
        text("DIRECT READS · no approval, mint or transfer\nOnly known addresses/token IDs. Not full portfolio discovery. Results are provider reports, not independent chain verification. One local request budget: 30 RPC calls/minute; time/response limits apply.");
        owner=field("Wallet address","0x…",false);try{if(getIntent().hasExtra("publicOwner"))owner.setText(ReadPolicy.address(getIntent().getStringExtra("publicOwner")));}catch(Exception ignored){}contract=field("Token/NFT contract (blank for CRO)","0x…",false);token=field("NFT token ID","0",false);multi=check("ERC-1155 quantity check (otherwise ERC-721 ownerOf)");
        button("Read CRO / ERC-20 balance",()->{final String a=owner.getText().toString().trim(),t=contract.getText().toString().trim();job(()->{JSONObject report=primary(readConnections()).balance(a,t).put("checkedAt",System.currentTimeMillis()).put("cached",false);workspace.snapshot("25:device","balance:"+a+":"+t,report);return report.toString(2);});});
        button("Check known NFT ownership",()->{final String a=owner.getText().toString().trim(),t=contract.getText().toString().trim(),id=token.getText().toString().trim();final boolean copies=multi.isChecked();job(()->{JSONObject report=primary(readConnections()).nft(a,t,id,copies).put("checkedAt",System.currentTimeMillis()).put("cached",false);workspace.snapshot("25:device","nft:"+a+":"+t+":"+id+":"+copies,report);return report.toString(2);});});
        button("Show cached read observations (device profile)",()->job(()->workspace.snapshots("25:device").toString(2)));
        hash=field("Transaction hash to inspect","0x… (64 hex)",false);
        button("Check receipt & save local observation",()->{final String h=hash.getText().toString().trim();final String a;try{a=account();}catch(Exception e){show(e.getMessage());return;}job(()->{JSONObject result=primary(readConnections()).receipt(h);workspace.receipt(a,h,result);return result.toString(2);});});
        text("OPTIONAL BACKGROUND RECEIPT OBSERVATIONS · OFF BY DEFAULT\nWorkManager timing is inexact (15-minute minimum, often delayed by Android/Doze/network/battery). At most 20 saved targets, 96 attempts or 48 hours each. Stops at first observed inclusion, NOT finality. No signing/resending or automatic backup-provider use. Changing/forgetting settings pauses checks; resume explicitly.");
        CheckBox unmetered=new CheckBox(this);unmetered.setText(R.string.receipt_unmetered_only);unmetered.setTextColor(Color.WHITE);unmetered.setChecked(ReceiptWatchScheduler.unmeteredOnly(this));body.addView(unmetered);
        button("Save background data policy & pause checks",()->{final boolean only=unmetered.isChecked();job(()->{ReceiptWatchScheduler.setUnmeteredOnly(this,only);return "Background data policy saved: "+(only?"unmetered networks only":"metered networks also permitted")+". Receipt checks paused; resume explicitly. Android decides which networks are metered. This policy does not affect foreground manual reads or other web requests.";});});
        button("Watch receipt above (read-only, bounded)",()->{final String a,h;try{a=account();h=ReadPolicy.hash(hash.getText().toString().trim());}catch(Exception e){show("Choose a valid profile and transaction hash");return;}new AlertDialog.Builder(this).setTitle("Enable background receipt observations?").setMessage("Hash: "+h+"\nProfile: "+a+"\nUses your saved PRIMARY provider and native credential while the app is closed. Public hashes are sent to that provider. No transaction is ever signed or sent. The job is best-effort, bounded and can be paused below. The saved background data policy applies (unmetered only by default). Imported backups never schedule watches.").setPositiveButton("Enable",(d,w)->job(()->{readConnections();watches.watch(a,h,System.currentTimeMillis());ReceiptWatchScheduler.resume(this);return "Receipt watch saved and scheduling requested. No timing guarantee, no transaction sent. Check checkpoints for results.";})).setNegativeButton("Cancel",null).show();});
        button("List receipt watch checkpoints",()->{final String a;try{a=account();}catch(Exception e){show(e.getMessage());return;}job(()->{watches.expire(System.currentTimeMillis());return new JSONObject().put("schedulingRequested",ReceiptWatchScheduler.enabled(this)).put("unmeteredOnly",ReceiptWatchScheduler.unmeteredOnly(this)).put("account",a).put("watches",watches.list(a)).put("warning","Scheduling requested is NOT proof Android ran the worker. Inclusion is not finality.").toString(2);});});
        button("Pause all background receipt checks",()->job(()->{ReceiptWatchScheduler.pause(this);return "Background receipt work cancelled/paused. In-flight reads are cancelled on worker stop. Checkpoints remain; time windows still expire.";}));
        button("Resume saved receipt checks",()->new AlertDialog.Builder(this).setTitle("Resume saved receipt observations?").setMessage("Uses your current saved primary provider for all still-active watch profiles. No automatic retry of a value transaction. Review checkpoints/provider first.").setPositiveButton("Resume",(d,w)->job(()->{readConnections();watches.expire(System.currentTimeMillis());if(watches.active()==0)throw new IllegalStateException("No active watches; start/restart a specific hash first");ReceiptWatchScheduler.resume(this);return "Background receipt scheduling requested. Android may delay execution.";})).setNegativeButton("Cancel",null).show());
        button("Remove receipt watch above",()->{final String a,h;try{a=account();h=ReadPolicy.hash(hash.getText().toString().trim());}catch(Exception e){show("Invalid profile/hash");return;}job(()->{watches.remove(a,h);if(watches.active()==0)ReceiptWatchScheduler.pause(this);return "Selected receipt watch removed. No on-chain change.";});});
        text("PERSONAL WORKSPACE · native SQLite\nThese records are device-local, separate from cloud creator drafts and browser storage. A profile address is an organizational label, NOT proof you own that wallet. No automatic cloud sync. Uninstall/clear-data loses local records unless exported. Draft database and exports are NOT separately encrypted; never store secrets here.");
        profile=field("Local profile address (blank = device profile)","0x… optional",false);try{if(getIntent().hasExtra("publicOwner"))profile.setText(ReadPolicy.address(getIntent().getStringExtra("publicOwner")));}catch(Exception ignored){}
        title=field("Draft title","My collection",false);document=field("Draft JSON object","{\"config\":{\"name\":\"My collection\"}}",false);document.setSingleLine(false);document.setMinLines(4);document.setMaxLines(12);
        button("Save a NEW native draft",()->{final String a,t=title.getText().toString(),json=document.getText().toString();try{a=account();}catch(Exception e){show(e.getMessage());return;}job(()->"Saved local draft "+workspace.save(a,t,new JSONObject(JsonBudget.check(json,65536,26)))+". No public registration or upload occurred.");});
        button("List local drafts / favorites / receipt observations",()->{final String a;try{a=account();}catch(Exception e){show(e.getMessage());return;}job(()->{JSONArray drafts=workspace.drafts(a),summaries=new JSONArray();for(int i=0;i<drafts.length();i++){JSONObject d=drafts.getJSONObject(i);summaries.put(new JSONObject().put("id",d.getString("id")).put("title",d.getString("title")).put("version",d.getInt("version")));}return new JSONObject().put("account",a).put("drafts",summaries).put("favorites",workspace.favorites(a)).put("receipts",workspace.receipts(a)).toString(2);});});
        button("Open / delete a native draft",()->{final String a;try{a=account();}catch(Exception e){show(e.getMessage());return;}try{JSONArray rows=workspace.drafts(a);String[] names=new String[rows.length()];for(int i=0;i<rows.length();i++)names[i]=rows.getJSONObject(i).getString("title");new AlertDialog.Builder(this).setTitle("Native drafts in selected profile").setItems(names,(d,i)->{try{JSONObject draft=rows.getJSONObject(i);title.setText(draft.getString("title"));document.setText(draft.getJSONObject("document").toString(2));new AlertDialog.Builder(this).setTitle("Draft opened").setMessage("Saving creates a new version as a new draft. Delete removes only this local record.").setPositiveButton("Keep",null).setNegativeButton("Delete",(dd,ww)->{workspace.delete(a,draft.optString("id"));show("Local draft deleted. No cloud/on-chain changes.");}).show();}catch(Exception e){show("Draft could not be opened");}}).setNegativeButton("Close",null).show();}catch(Exception e){show("Workspace unavailable");}});
        button("Favorite contract above",()->favorite(true));button("Remove favorite contract above",()->favorite(false));
        button("Export selected profile (unencrypted JSON)",()->{try{pendingExport=workspace.backup(account()).toString().getBytes(java.nio.charset.StandardCharsets.UTF_8);new AlertDialog.Builder(this).setTitle("Export personal data?").setMessage("Drafts/favorites become a readable JSON file at the location you choose. No connection credentials or wallet keys are included. Keep it private.").setPositiveButton("Choose file",(d,w)->{Intent intent=new Intent(Intent.ACTION_CREATE_DOCUMENT);intent.setType("application/json");intent.addCategory(Intent.CATEGORY_OPENABLE);intent.putExtra(Intent.EXTRA_TITLE,"rift-personal-workspace.json");startActivityForResult(intent,EXPORT);}).setNegativeButton("Cancel",(d,w)->pendingExport=null).show();}catch(Exception e){show("Export failed; check profile/storage");}});
        button("Import workspace JSON (merge, no overwrites)",()->{Intent intent=new Intent(Intent.ACTION_OPEN_DOCUMENT);intent.addCategory(Intent.CATEGORY_OPENABLE);intent.setType("application/json");startActivityForResult(intent,IMPORT);});
        button("Clear selected local profile",()->{final String a;try{a=account();}catch(Exception e){show(e.getMessage());return;}new AlertDialog.Builder(this).setTitle("Delete local profile records?").setMessage("Does NOT cancel on-chain listings/offers, revoke approvals or delete cloud drafts. Export first.").setPositiveButton("Delete local",(d,w)->job(()->{watches.clear(a);workspace.clear(a);try(DiscoveryIndexStore index=new DiscoveryIndexStore(this)){index.clearAccount(a);}if(watches.active()==0)ReceiptWatchScheduler.pause(this);return "Local profile cleared only.";})).setNegativeButton("Cancel",null).show();});
        text("RESULTS (selectable; inspect before sharing)");output=new TextView(this);output.setTextColor(Color.rgb(184,255,67));output.setTextIsSelectable(true);output.setText(R.string.no_operation);body.addView(output);
        button("Return to app",this::finish);
    }
    private void favorite(boolean add){final String a,t=contract.getText().toString().trim();try{a=account();}catch(Exception e){show(e.getMessage());return;}job(()->{workspace.favorite(a,t,add);return "Local favorite "+(add?"saved":"removed")+". No shared account change.";});}
    @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(result!=RESULT_OK||data==null||data.getData()==null){pendingExport=null;return;}Uri uri=data.getData();if(!"content".equals(uri.getScheme())){show("Only document-provider content URIs are accepted");return;}
        if(request==EXPORT){final byte[] bytes=pendingExport;pendingExport=null;if(bytes==null){show("Export expired. Start export again.");return;}job(()->{try(OutputStream out=getContentResolver().openOutputStream(uri,"wt")){if(out==null)throw new IOException();out.write(bytes);}return "Personal profile exported. Credentials/receipt observations were not exported. Backup is not encrypted.";});}
        if(request==IMPORT){final String a;try{a=account();}catch(Exception e){show(e.getMessage());return;}new AlertDialog.Builder(this).setTitle("Import into selected profile?").setMessage("Maximum 4 MiB; schema/chain/profile must match. Drafts are added as new records, so repeated imports create copies. Import is atomic and never overwrites credentials/cloud data.").setPositiveButton("Import",(d,w)->job(()->{ByteArrayOutputStream bytes=new ByteArrayOutputStream();try(InputStream in=getContentResolver().openInputStream(uri)){if(in==null)throw new IOException();byte[] buffer=new byte[4096];int n;while((n=in.read(buffer))!=-1){if(bytes.size()+n>4194304)throw new IllegalArgumentException("Import exceeds 4 MiB");bytes.write(buffer,0,n);}}return "Imported "+workspace.restore(a,new JSONObject(JsonBudget.check(bytes.toString("UTF-8"),4194304,32)))+" draft(s). Favorites merged; no public writes.";})).setNegativeButton("Cancel",null).show();}
    }
    @Override protected void onDestroy(){pendingExport=null;io.execute(()->{workspace.close();watches.close();});io.shutdown();super.onDestroy();}
}
